import math

def tournament_bribingRequirements(n, bribes):
    bribes_count = [bribe for bribe in bribes if bribe != -1]
    bribes_count.sort(reverse=True)
    bribes_count.append(1)

    required_cost = 0
    for i in range(1, math.ceil(math.log2(n))):
        for bribe in bribes_count[i:]:
            required_cost += bribes[bribe - 1]
        if n % (2 ** i) != 0:
            break

    return required_cost

