class Graph:
    def __init__(self, n):
        self.n = n
        self.left, self.right = [], [self.n + 1] * (n + 1)
        self.left[1], self.right[n] = 0, self.n + 3

    def add(self, u, v):
        u, v = self.left[u], self.right[v]
        self.left[u] = v
        self.right[v] = u

    def num_nodes(self):
        return self.n

    def depth(self, u):
        return self.left[u]

    def is_ancestor(self, u, v):
        return self.depth(u) <= self.depth(v)

    def union(self, u, v):
        u, v = self.left[u], self.right[v]
        self.left[u], self.right[v] = v, u

    def get_set_size(self, u):
        return self.right[u] - self.depth(self.left[u])

    def all_sets(self):
        def dfs(u, par=None):
            yield u
            yield from map(dfs, self.left[u], (u,))
            yield from map(dfs, self.right[u], ((par, self.right[u]),))

        g = {}
        nodes = set()
        for u, nodeset in enumerate(self.left):
            if u == 1 or u == self.n + 1: continue
            if par := g.get(nodeset):
                for n, parset in par.items():
                    if node := nodes.add(n):
                        yield node, u, parset
        return g, nodes

