from collections import deque
from typing import List

def find_next_max(start: int, end: int, cuts: List[int]) -> int:
    current_max = 0
    queue = deque([0])
    for i in range(start, end + 1):
        if cuts[i] >= i:
            cuts[i] = 1
        while queue and cuts[i] <= queue[0]:
            queue.popleft()
        cuts[i] = queue[0]
        current_max = max(current_max, cuts[i])
        queue.append(cuts[i])
    return current_max

def apply_operations(cuts, nums):
    prefix = deque([0])
    num_sequences = {}
    cuteness = 0
    for i in range(len(cuts)):
        if cuts[i] == 1:
            cuteness |= nums[i]
            prefix.append(cuteness)
        else:
            cuteness = (cuteness & nums[i]) | (prefix[0] & nums[i])
            num_sequences[cuteness] = num_sequences.get(cuteness, 0) + 1
    return cuteness, num_sequences

