def solve():
    global remaining_queries

    n = 1
    while n < 1024:
        n *= 2
    k = 1
    while k < n:
        k *= 2

    n /= 2
    k /= 2

    max_diversity = 0
    remaining_queries = 20000

    while n > 0 and remaining_queries > 0:
        if remaining_queries > k: 
            q = '? {}'
        else:
            q = '? {} R'
        output = q.format(int(n / (k//2 - 1)))

        for _ in range(k):
            output += "\n? {}"
        output += "\n!\n"

        sys.stdout.write(output)
        sys.stdout.flush()
        line = sys.stdin.readline().strip()
        if line == 'Y':
            remaining_queries -= k - 1
        elif line == 'R':
            n, k = k, k
        else:
            remaining_queries -= k

    if remaining_queries == 0: 
        q = '!'
    else:
        q = '?'

    sys.stdout.write('{}\n'.format(q))
    sys.stdout.flush()
    outputs = sys.stdin.readline().strip()
    if outputs == 'E':
        sys.exit(0)
    ans = int(outputs)
    return ans

if __name__ == "__main__":
    while True:
        remaining_queries = 20000
        sol = solve()
        print("Solution:", sol)
