    """
    return math.sqrt((point2[0] - point1[0])**2 + (point2[1] - point1[1])**2)

def area_bottom_left_origin(polygon):
    """
    Calculate the area of the region covered by the polygon when viewed from the bottom-left corner.
    """
    covered_area = 0.0
    for i in range(len(polygon)):
        if i == len(polygon)-1:
            x, y = polygon[0]
        else:
            x, y = polygon[i]
        for j in range(-1, len(polygon)):
            if j == -1 or i == len(polygon)-1:
                x1, y1 = polygon[0]
            else:
                x1, y1 = polygon[j]
            if x - x1 < 0 < y - y1:
                covered_area += (x - x1) * distance((x1, y1), (x, y))
    return covered_area

