import sys

def find_min_uncovered_area(n, vertices):
    vertices.sort(key=lambda x: x[1])  # Sort vertices by y-coordinate
    dp = [[0] * n for _ in range(n)]
    for ind, (x, y) in enumerate(vertices):
        for a in range(ind):
            dp[a][ind] = min(dp[a][ind], abs(y - vertices[a][1]) * abs(x - vertices[a][0]))

    # Calculate the convex hull
    for i, (x, y) in enumerate(vertices):
        for ind, (x2, y2) in enumerate(vertices[i+1:], start=i+1):
            if not (x2 < x and y2 > y) and not (y2 == y and x2 < x):
                dp[i][ind] = max(dp[i][ind], abs(y2 - y) * abs(x2 - x))

    def calculate_uncovered_area(dp, vertices, index):
        full = dp[index][index]
        uncovered = full
        sub_sum = full
        for i in range(index):
            sub_sum -= dp[i][index]
            uncovered = min(uncovered, full - sub_sum)
        for i in range(index+1, n):
            sub_sum -= dp[index][i]
            uncovered = min(uncovered, full - sub_sum)
        return uncovered - full

    # For each vertex, calculate the minimum uncovered area on both sides of the vertices
    out = sys.maxsize
    for i in range(n):
        uncovered = calculate_uncovered_area(dp, vertices, i)
        if uncovered < out:
            out = uncovered
    return out

