from collections import Counter

def count_remaining_pairs(n, m, difficulties):
    # Construct the row matrix with the new difficulty elements
    current_row = [0] * (n + 1)
    for i in range(1, n + 1):
        if difficulties[i-1] == 1:
            current_row[i] = 1  # First element from next diff[i]
            for j in range(i + 1, n + 1):
                current_row[j] = 0  # Nothing more with sparse zeros
        else:
            current_row[i] = difficulties[i-1]
            for j in range(i + 1, n + 1):
                current_row[j] = current_row[j-1]  # Cover all + 0 diff[i]
    # Matrix Powers start here
    right_table = [[0, 1], [1, 0]]
    for i in range(10):
        for row in range(2):
            for col in range(n + 1):
                right_table[row][col] = ((right_table[row][col] * right_table[1][1]) % mod)
    # taking mod
    ans = 0
    for i in range(n + 1):
        ans = (ans + (current_row[i] * (right_table[0][1] % mod) ** (m % (i + 2) * 2) % mod)) % mod
