import math

def is_lucky_number(num):
    return '4' in str(num) and '7' in str(num) and len(str(num)) > 1

def shift_segment(l, r, change_count, max_position, visited):
    if change_count > math.floor(max_position / 2):
        return 0

    if is_lucky_number(max_position - change_count):
        return 1

    results = 0
    for i in range(l, r + 1):
        if visited[i]:
            continue

        next_position = max_position - max(change_count, (r - i + l) // 2 - 1)
        if not is_lucky_number(next_position):
            break

        visited[i] = True
        results += shift_segment(l, i - 1, change_count - 2, next_position, visited)
        visited[i] = False

    return results

def max_full_lucky_numbers(n, k):
    max_position = max(nums[0])
    visited = [False] * (max_position + 1)
    visited[0] = True
    return math.floor(k / 2) + shift_segment(0, n - 1, k, max_position, visited)

