from itertools import combinations

def sign(p, q, r):
    return (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])

def skew(a, b):
    return a[0] * b[1] - a[1] * b[0]

def is_convex(polygon):
    tuples = combinations(polygon, 2)
    return all(sign(p, p + s, q) < 0 for s in tuples for q in tuples)

def count_shapes(x1, y1, x2, y2):
    m, k = min(y1, y2), max(y1, y2)
    n, h = min(x1, x2), max(x1, x2)
    return sum(all(s * t <= 0 for t in range(m + 1, y1)) for s in range(k + 1, h + 1))

def calculate_covered_area(polygon, point):
    min_distance = float('inf')
    for corner in polygon:
        distance = skew(point - (corner, 0), corner - (point, 0))
        if distance < min_distance:
            min_distance = distance
    return area - min(min_distance * abs(min_distance) // 2, 0.99)

