from collections import deque

def bfs(grid, i, j):
    visits = set()
    q = deque([(i, j)])
    level = {(i, j): 0}
    while q:
        (i, j) = q.popleft()
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for di, dj in directions:
            ii, jj = i + di, j + dj
            if 0 <= ii < n and 0 <= jj < m and grid[ii][jj] > grid[i][j] and (ii, jj) not in level and (ii, jj) not in visits:
                level[(ii, jj)] = level[(i, j)] + 1
                q.append((ii, jj))
                visits.add((ii, jj))
    return level

def get_badly_painted_regions(grid, a, b, x):
    n, m, _, _, _, _, x = map(int, input().split())
    a = list(map(int, input().split()))
    b = list(map(int, input().split()))
    grid = [[0] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            grid[i][j] = min(a[i] + b[j], x)
    level = bfs(grid, 0, 0)
    visited = set()
    ans = 0
    for i in range(n):
        for j in range(m):
            if level[(i, j)] % 2 == 0 and grid[i][j] > 0 and (i, j) not in visited and level[(i, j)] > 0:
                visited.add((i, j))
                for ii, jj in [(i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)]:
                    if 0 <= ii < n and 0 <= jj < m and grid[ii][jj] > 0 and (ii, jj) not in visited:
                        ans += 1
                        visited.add((ii, jj))
    return ans

