def maximize_lucky_numbers_moves(n, k):
    if k >= n * 2:
        return n

    effective_shift = k - (n * sqrt(n) + sqrt(n)) // 2
    move_left = 1

    if effective_shift >= 0:
        if effective_shift % 2 == 0:
            move_left += effective_shift // 2 - 1
        else:
            move_left += (effective_shift + 1) // 2 - 1

    if move_left >= n:
        return move_left

    prev_min = move_left
    for i in range(1, 10):
        current_min = prev_min + (10 ** (move_left // 10) - 10 ** (prev_min // 10))
        if current_min > k:
            break
        move_left += (current_min - k) // 10 + 1
        prev_min += 1

    return move_left

